mapper.insert:
INSERT INTO attendance_record (
    employee_id, work_date, check_in_time, status, tardy_reason
) VALUES (
            #{employeeId}, #{workDate}, #{checkInTime}, #{status}, #{tardyReason}
        )

mapper.update:
UPDATE attendance_record
SET check_out_time = #{checkOutTime},
    status = #{status}
WHERE employee_id = #{employeeId}
  AND work_date = #{workDate}
  AND check_out_time IS NULL

UPDATE attendance_record
SET check_in_time = #{checkInTime},
    check_out_time = #{checkOutTime},
    status = #{status},
    modify_reason = #{modifyReason}
WHERE attendance_id = #{attendanceId}

mapper.select:
SELECT attendance_id as attendanceId, employee_id as employeeId, work_date as workDate, check_in_time as checkInTime, check_out_time as checkOutTime, status as status, tardy_reason as tardyReason, modify_reason as modifyReason FROM attendance_record WHERE employee_id = #{employeeId} AND DATE_FORMAT(work_date, '%Y-%m') = #{targetMonth}
AND status = #{status}
ORDER BY work_date DESC
